<?php
namespace Tests\Feature;
use App\Models\Catalog\Item;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Tests\TestCase;
class MemberBackendTest extends TestCase {
 use RefreshDatabase;
 private function roleUser(string $role,bool $active=true):User{$now=now();$id=DB::table('users')->insertGetId(['name'=>'Test '.ucfirst($role),'email'=>$role.'-'.uniqid().'@example.test','password'=>Hash::make('secret-password'),'role'=>$role,'is_active'=>$active,'created_at'=>$now,'updated_at'=>$now]);DB::table($role==='admin'?'admins':'members')->insert(['user_id'=>$id]);return User::findOrFail($id);}
 private function item(string $status=Item::AVAILABLE,string $name='The Yesterday Watch'):int{return DB::table('items')->insertGetId(['unit_code'=>'UNIT-'.uniqid(),'name'=>$name,'description'=>'Test prop','status'=>$status,'created_at'=>now(),'updated_at'=>now()]);}
 private function category(string $name,bool $archived=false):int{return DB::table('categories')->insertGetId(['name'=>$name,'description'=>null,'is_archived'=>$archived,'created_at'=>now(),'updated_at'=>now()]);}
 private function attach(int $item,int $category):void{DB::table('item_category')->insert(['item_id'=>$item,'category_id'=>$category]);}
 private function loan(int $memberId,array $itemIds,string $status='pending',?\DateTimeInterface $dueAt=null):array{$now=now();$id=DB::table('loan_requests')->insertGetId(['member_id'=>$memberId,'status'=>$status,'requested_at'=>$now->copy()->subDays(6),'handed_over_at'=>$status==='active'?$now->copy()->subDays(5):null,'due_at'=>$dueAt,'created_at'=>$now,'updated_at'=>$now]);$details=[];foreach($itemIds as $itemId)$details[]=DB::table('loan_request_items')->insertGetId(['loan_request_id'=>$id,'item_id'=>$itemId,'created_at'=>$now]);return ['id'=>$id,'details'=>$details];}
 private function fine(int $detailId,int $adminId,string $status='unpaid',int $amount=10000):int{return DB::table('fines')->insertGetId(['loan_request_item_id'=>$detailId,'recorded_by'=>$adminId,'amount'=>$amount,'status'=>$status,'assessed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}
 private function unitCode(int $itemId):string{return DB::table('items')->where('id',$itemId)->value('unit_code');}

 // --- Authentication and authorization (F-01) ---
 public function test_member_dashboard_requires_authentication():void{$this->getJson('/member/dashboard')->assertUnauthorized();}
 public function test_role_login_pages_render_successfully():void{$this->get('/admin/login')->assertOk()->assertSee('Admin Command Login');$this->get('/member/login')->assertOk()->assertSee('Portal Peminjaman Member');}
 public function test_guest_browser_requests_redirect_to_role_specific_login_pages():void{$this->get('/member/dashboard')->assertRedirect(route('member.login.view'));$this->get('/admin/dashboard')->assertRedirect(route('admin.login.view'));}
 public function test_missing_admin_detail_views_render_for_authorized_admin():void{$admin=$this->roleUser('admin');$category=$this->category('View Test Category');$item=$this->item();$member=$this->roleUser('member');$this->actingAs($admin)->get("/admin/categories/{$category}")->assertOk()->assertSee('View Test Category');$this->get("/admin/items/{$item}")->assertOk()->assertSee($this->unitCode($item));$this->get("/admin/members/{$member->id}")->assertOk()->assertSee($member->email);}
 public function test_missing_member_views_render_for_authorized_member():void{$member=$this->roleUser('member');$this->category('Member View Category');$loan=$this->loan($member->id,[$this->item()]);$this->actingAs($member)->get('/member/catalog/categories')->assertOk()->assertSee('Member View Category');$this->get("/member/loan-requests/{$loan['id']}")->assertOk()->assertSee('Detail Peminjaman Props');}
 public function test_admin_cannot_access_member_area():void{$this->actingAs($this->roleUser('admin'))->getJson('/member/dashboard')->assertForbidden();}
 public function test_inactive_member_cannot_access_member_area():void{$this->actingAs($this->roleUser('member',false))->getJson('/member/dashboard')->assertForbidden();}
 public function test_member_cannot_access_admin_routes():void{$this->actingAs($this->roleUser('member'))->getJson('/admin/items')->assertForbidden();}
 public function test_member_login_rejects_admin_account():void{$u=$this->roleUser('admin');$this->postJson('/member/login',['email'=>$u->email,'password'=>'secret-password'])->assertForbidden();}
 public function test_member_login_rejects_wrong_password_without_revealing_account():void{$u=$this->roleUser('member');$this->postJson('/member/login',['email'=>$u->email,'password'=>'wrong'])->assertUnprocessable()->assertJsonPath('errors.email.0','Email atau password tidak valid.');$this->postJson('/member/login',['email'=>'nobody@example.test','password'=>'wrong'])->assertUnprocessable()->assertJsonPath('errors.email.0','Email atau password tidak valid.');}
 public function test_member_login_rejects_inactive_member():void{$u=$this->roleUser('member',false);$this->postJson('/member/login',['email'=>$u->email,'password'=>'secret-password'])->assertForbidden();}
 public function test_member_login_and_logout_succeed():void{$u=$this->roleUser('member');$this->postJson('/member/login',['email'=>$u->email,'password'=>'secret-password'])->assertOk()->assertJsonPath('data.role','member');$this->postJson('/member/logout')->assertOk();$this->getJson('/member/dashboard')->assertUnauthorized();}

 // --- Profile (F-02) ---
 public function test_member_can_view_and_update_own_profile():void{$u=$this->roleUser('member');$this->actingAs($u)->getJson('/member/profile')->assertOk()->assertJsonPath('data.email',$u->email)->assertJsonMissingPath('data.password');$this->patchJson('/member/profile',['name'=>'Nama Baru','email'=>'baru@example.test'])->assertOk()->assertJsonPath('data.name','Nama Baru');$this->assertDatabaseHas('users',['id'=>$u->id,'name'=>'Nama Baru','email'=>'baru@example.test','role'=>'member']);}
 public function test_password_change_requires_correct_current_password():void{$u=$this->roleUser('member');$this->actingAs($u)->patchJson('/member/profile',['password'=>'new-password-123','password_confirmation'=>'new-password-123','current_password'=>'wrong'])->assertUnprocessable()->assertJsonValidationErrors(['current_password']);$this->patchJson('/member/profile',['password'=>'new-password-123','password_confirmation'=>'new-password-123','current_password'=>'secret-password'])->assertOk();$this->assertTrue(Hash::check('new-password-123',$u->fresh()->password));}
 public function test_member_cannot_take_email_of_another_user():void{$other=$this->roleUser('member');$u=$this->roleUser('member');$this->actingAs($u)->patchJson('/member/profile',['email'=>$other->email])->assertUnprocessable()->assertJsonValidationErrors(['email']);}

 // --- Catalog (F-05) ---
 public function test_catalog_lists_non_archived_units_and_hides_archived():void{$available=$this->item();$loaned=$this->item(Item::LOANED);$archived=$this->item(Item::ARCHIVED);$res=$this->actingAs($this->roleUser('member'))->getJson('/member/catalog/items')->assertOk();$codes=collect($res->json('data.data'))->pluck('unit_code');$this->assertTrue($codes->contains($this->unitCode($available)));$this->assertTrue($codes->contains($this->unitCode($loaned)));$this->assertFalse($codes->contains($this->unitCode($archived)));$res->assertJsonFragment(['unit_code'=>$this->unitCode($loaned),'is_available'=>false]);}
 public function test_catalog_available_filter_hides_reserved_and_loaned_units():void{$available=$this->item();$this->item(Item::RESERVED);$this->item(Item::LOANED);$res=$this->actingAs($this->roleUser('member'))->getJson('/member/catalog/items?available=1')->assertOk();$this->assertSame([$this->unitCode($available)],collect($res->json('data.data'))->pluck('unit_code')->all());}
 public function test_catalog_search_by_name_and_filter_by_category():void{$relics=$this->category('Relics');$watch=$this->item(Item::AVAILABLE,'The Yesterday Watch');$door=$this->item(Item::AVAILABLE,'The Forgotten Door');$this->attach($door,$relics);$this->actingAs($this->roleUser('member'));$this->getJson('/member/catalog/items?search=yesterday')->assertOk()->assertJsonFragment(['unit_code'=>$this->unitCode($watch)])->assertJsonMissing(['unit_code'=>$this->unitCode($door)]);$this->getJson("/member/catalog/items?category_id={$relics}")->assertOk()->assertJsonFragment(['unit_code'=>$this->unitCode($door)])->assertJsonMissing(['unit_code'=>$this->unitCode($watch)]);}
 public function test_item_detail_shows_categories_and_availability_and_hides_archived():void{$relics=$this->category('Relics');$item=$this->item();$this->attach($item,$relics);$archived=$this->item(Item::ARCHIVED);$this->actingAs($this->roleUser('member'));$this->getJson("/member/catalog/items/{$item}")->assertOk()->assertJsonPath('data.is_available',true)->assertJsonPath('data.categories.0.name','Relics');$this->getJson("/member/catalog/items/{$archived}")->assertNotFound();}
 public function test_catalog_categories_exclude_archived():void{$this->category('Relics');$this->category('Old',true);$this->actingAs($this->roleUser('member'))->getJson('/member/catalog/categories')->assertOk()->assertJsonFragment(['name'=>'Relics'])->assertJsonMissing(['name'=>'Old']);}

 // --- Loan request submission (F-07) ---
 public function test_member_can_submit_request_for_two_available_units():void{$m=$this->roleUser('member');$a=$this->item();$b=$this->item();$now=now()->startOfSecond();$this->travelTo($now);$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$a,$b]])->assertCreated()->assertJsonPath('data.status','pending')->assertJsonPath('data.unit_count',2)->assertJsonPath('data.member_id',$m->id);$loan=DB::table('loan_requests')->where('member_id',$m->id)->first();$this->assertSame('pending',$loan->status);$this->assertSame($now->format('Y-m-d H:i:s'),$loan->requested_at);$this->assertNull($loan->reviewed_at);$this->assertSame(2,DB::table('loan_request_items')->where('loan_request_id',$loan->id)->count());$this->assertDatabaseHas('items',['id'=>$a,'status'=>Item::AVAILABLE]);$this->assertDatabaseHas('items',['id'=>$b,'status'=>Item::AVAILABLE]);}
 public function test_request_rejects_more_than_two_units_duplicates_and_unknown_units():void{$m=$this->roleUser('member');$a=$this->item();$b=$this->item();$c=$this->item();$this->actingAs($m);$this->postJson('/member/loan-requests',['item_ids'=>[$a,$b,$c]])->assertUnprocessable()->assertJsonValidationErrors(['item_ids']);$this->postJson('/member/loan-requests',['item_ids'=>[$a,$a]])->assertUnprocessable();$this->postJson('/member/loan-requests',['item_ids'=>[999999]])->assertUnprocessable();$this->postJson('/member/loan-requests',[])->assertUnprocessable();$this->assertDatabaseCount('loan_requests',0);}
 public function test_request_rejects_unavailable_unit_with_reason():void{$m=$this->roleUser('member');$ok=$this->item();$reserved=$this->item(Item::RESERVED);$res=$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$ok,$reserved]])->assertUnprocessable();$this->assertStringContainsString($this->unitCode($reserved),$res->json('message'));$this->assertDatabaseCount('loan_requests',0);$archived=$this->item(Item::ARCHIVED);$this->postJson('/member/loan-requests',['item_ids'=>[$archived]])->assertUnprocessable();}
 public function test_request_rejects_when_two_unit_cap_would_be_exceeded():void{$m=$this->roleUser('member');$this->loan($m->id,[$this->item(Item::LOANED)],'active',now()->addDay());$this->actingAs($m);$this->postJson('/member/loan-requests',['item_ids'=>[$this->item(),$this->item()]])->assertUnprocessable();$this->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertCreated();}
 public function test_approved_reservations_count_toward_cap():void{$m=$this->roleUser('member');$this->loan($m->id,[$this->item(Item::RESERVED),$this->item(Item::RESERVED)],'approved');$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertUnprocessable();}
 public function test_pending_units_count_toward_cap_at_submission():void{$m=$this->roleUser('member');$this->loan($m->id,[$this->item(),$this->item()],'pending');$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertUnprocessable();}
 public function test_returned_and_rejected_requests_do_not_count_toward_cap():void{$m=$this->roleUser('member');$this->loan($m->id,[$this->item(),$this->item()],'returned',now()->subDays(2));$this->loan($m->id,[$this->item(),$this->item()],'rejected');$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$this->item(),$this->item()]])->assertCreated();}
 public function test_member_with_unpaid_fine_cannot_submit_request():void{$admin=$this->roleUser('admin');$m=$this->roleUser('member');$old=$this->loan($m->id,[$this->item()],'returned',now()->subDays(2));$this->fine($old['details'][0],$admin->id);$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertUnprocessable();$this->assertSame(1,DB::table('loan_requests')->count());}
 public function test_member_with_paid_fine_can_submit_request():void{$admin=$this->roleUser('admin');$m=$this->roleUser('member');$old=$this->loan($m->id,[$this->item()],'returned',now()->subDays(2));$this->fine($old['details'][0],$admin->id,'paid');$this->actingAs($m)->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertCreated();}
 public function test_inactive_member_cannot_submit_request():void{$this->actingAs($this->roleUser('member',false))->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertForbidden();$this->assertDatabaseCount('loan_requests',0);}

 // --- Own transactions, history and fines (F-13, BR-18) ---
 public function test_member_sees_only_own_loan_requests():void{$me=$this->roleUser('member');$other=$this->roleUser('member');$mine=$this->loan($me->id,[$this->item()]);$theirs=$this->loan($other->id,[$this->item()]);$this->actingAs($me);$ids=collect($this->getJson('/member/loan-requests')->assertOk()->json('data.data'))->pluck('id');$this->assertTrue($ids->contains($mine['id']));$this->assertFalse($ids->contains($theirs['id']));$this->getJson("/member/loan-requests/{$mine['id']}")->assertOk()->assertJsonPath('data.id',$mine['id']);$this->getJson("/member/loan-requests/{$theirs['id']}")->assertNotFound();}
 public function test_loan_request_list_can_filter_by_status():void{$me=$this->roleUser('member');$pending=$this->loan($me->id,[$this->item()]);$returned=$this->loan($me->id,[$this->item()],'returned',now()->subDay());$ids=collect($this->actingAs($me)->getJson('/member/loan-requests?status=returned')->assertOk()->json('data.data'))->pluck('id');$this->assertTrue($ids->contains($returned['id']));$this->assertFalse($ids->contains($pending['id']));}
 public function test_active_loan_exposes_overdue_days_and_estimated_fine():void{$me=$this->roleUser('member');$now=now()->startOfSecond();$this->travelTo($now);$loan=$this->loan($me->id,[$this->item(Item::LOANED),$this->item(Item::LOANED)],'active',$now->copy()->subDays(2)->subHour());$this->actingAs($me)->getJson("/member/loan-requests/{$loan['id']}")->assertOk()->assertJsonPath('data.is_overdue',true)->assertJsonPath('data.overdue_full_days',2)->assertJsonPath('data.estimated_fine',40000)->assertJsonPath('data.total_fine',0);}
 public function test_active_loan_less_than_24_hours_late_has_zero_estimated_fine():void{$me=$this->roleUser('member');$now=now()->startOfSecond();$this->travelTo($now);$loan=$this->loan($me->id,[$this->item(Item::LOANED)],'active',$now->copy()->subHours(23)->subMinutes(59));$this->actingAs($me)->getJson("/member/loan-requests/{$loan['id']}")->assertOk()->assertJsonPath('data.is_overdue',true)->assertJsonPath('data.overdue_full_days',0)->assertJsonPath('data.estimated_fine',0);}
 public function test_member_sees_only_own_fines():void{$admin=$this->roleUser('admin');$me=$this->roleUser('member');$other=$this->roleUser('member');$mine=$this->loan($me->id,[$this->item()],'returned',now()->subDays(2));$theirs=$this->loan($other->id,[$this->item()],'returned',now()->subDays(2));$myFine=$this->fine($mine['details'][0],$admin->id);$theirFine=$this->fine($theirs['details'][0],$admin->id,'paid',20000);$ids=collect($this->actingAs($me)->getJson('/member/fines')->assertOk()->json('data.data'))->pluck('id');$this->assertTrue($ids->contains($myFine));$this->assertFalse($ids->contains($theirFine));}
 public function test_dashboard_summarises_allocation_fines_and_eligibility():void{$admin=$this->roleUser('admin');$me=$this->roleUser('member');$this->actingAs($me)->getJson('/member/dashboard')->assertOk()->assertJsonPath('data.allocation.remaining_units',2)->assertJsonPath('data.eligibility.can_request',true);$this->loan($me->id,[$this->item(Item::LOANED)],'active',now()->subDays(2));$old=$this->loan($me->id,[$this->item()],'returned',now()->subDays(9));$this->fine($old['details'][0],$admin->id);$this->getJson('/member/dashboard')->assertOk()->assertJsonPath('data.allocation.allocated_units',1)->assertJsonPath('data.allocation.remaining_units',1)->assertJsonPath('data.requests.active',1)->assertJsonPath('data.requests.overdue',1)->assertJsonPath('data.fines.unpaid_count',1)->assertJsonPath('data.fines.unpaid_amount',10000)->assertJsonPath('data.eligibility.can_request',false);}

 // --- End-to-end: Member submits, Admin processes, Member sees the outcome (flowcharts 5.1 to 5.3) ---
 public function test_full_workflow_from_member_request_to_paid_fine():void{
  $admin=$this->roleUser('admin');$member=$this->roleUser('member');$item=$this->item();$now=now()->startOfSecond();$this->travelTo($now);
  $loanId=$this->actingAs($member)->postJson('/member/loan-requests',['item_ids'=>[$item]])->assertCreated()->json('data.id');
  $this->actingAs($admin)->postJson("/admin/loan-requests/{$loanId}/approve")->assertOk();
  $this->actingAs($member)->getJson("/member/loan-requests/{$loanId}")->assertOk()->assertJsonPath('data.status','approved')->assertJsonPath('data.handover_deadline_at',$now->copy()->addDay()->toJSON());
  $this->assertDatabaseHas('items',['id'=>$item,'status'=>Item::RESERVED]);
  $this->actingAs($admin)->postJson("/admin/loan-requests/{$loanId}/handover")->assertOk();
  $this->actingAs($member)->getJson("/member/loan-requests/{$loanId}")->assertOk()->assertJsonPath('data.status','active')->assertJsonPath('data.due_at',$now->copy()->addDays(5)->toJSON())->assertJsonPath('data.is_overdue',false);
  $this->travelTo($now->copy()->addDays(6)->addSecond());
  $this->actingAs($member)->getJson("/member/loan-requests/{$loanId}")->assertOk()->assertJsonPath('data.is_overdue',true)->assertJsonPath('data.overdue_full_days',1)->assertJsonPath('data.estimated_fine',10000);
  $this->actingAs($admin)->postJson("/admin/loan-requests/{$loanId}/confirm-return")->assertOk();
  $this->actingAs($member)->getJson("/member/loan-requests/{$loanId}")->assertOk()->assertJsonPath('data.status','returned')->assertJsonPath('data.total_fine',10000)->assertJsonPath('data.unpaid_fine',10000)->assertJsonPath('data.estimated_fine',0);
  $this->getJson('/member/fines?status=unpaid')->assertOk()->assertJsonFragment(['amount'=>10000,'status'=>'unpaid']);
  $this->getJson('/member/dashboard')->assertOk()->assertJsonPath('data.eligibility.can_request',false);
  $this->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertUnprocessable();
  $fineId=DB::table('fines')->value('id');
  $this->actingAs($admin)->postJson("/admin/fines/{$fineId}/confirm-payment")->assertOk();
  $this->actingAs($member)->getJson('/member/dashboard')->assertOk()->assertJsonPath('data.eligibility.can_request',true)->assertJsonPath('data.fines.unpaid_count',0);
  $this->postJson('/member/loan-requests',['item_ids'=>[$this->item()]])->assertCreated();
 }
}
